def load_users(path):
    users = []
    with open(path) as f:
        for line in f:
            parts = line.strip().split(",")
            if len(parts) < 3:
                continue
            user = {"id": int(parts[0]), "name": parts[1], "email": parts[2]}
            users.append(user)
    return users


def find_user(users, user_id):
    for user in users:
        if user["id"] == user_id:
            return user
    return None


def active_emails(users, active_ids):
    emails = []
    for user in users:
        if user["id"] in active_ids:
            emails.append(user["email"])
    return emails

